   156	func importAttachment(v *Variant) (string, error) {
   157		if v.Attachment == nil {
   158			if v.attachmentSet {
   159				return "null", nil
   160			}
   161			return "", nil
   162		}
   163	
   164		attachment := convert(v.Attachment)
   165		if raw, ok := attachment.(string); ok && json.Valid([]byte(raw)) {
   166			var compact bytes.Buffer
   167			if err := json.Compact(&compact, []byte(raw)); err != nil {
   168				return "", err
   169			}
   170			return compact.String(), nil
   171		}
   172	
   173		data, err := json.Marshal(attachment)
   174		if err != nil {
   175			return "", err
   176		}
   177		return string(data), nil
