   180	// convert recursively changes YAML's interface-keyed maps to string-keyed maps
   181	// so they can be encoded as JSON.
   182	func convert(value interface{}) interface{} {
   183		switch value := value.(type) {
   184		case map[interface{}]interface{}:
   185			converted := make(map[string]interface{}, len(value))
   186			for key, item := range value {
   187				converted[fmt.Sprint(key)] = convert(item)
   188			}
   189			return converted
   190		case map[string]interface{}:
   191			converted := make(map[string]interface{}, len(value))
   192			for key, item := range value {
   193				converted[key] = convert(item)
   194			}
   195			return converted
   196		case []interface{}:
   197			converted := make([]interface{}, len(value))
   198			for index, item := range value {
   199				converted[index] = convert(item)
   200			}
   201			return converted
   202		default:
   203			return value
   204		}
   205	}
