   212		}
   213		var fields map[interface{}]interface{}
   214		if err := unmarshal(&fields); err != nil {
   215			return err
   216		}
   217	
   218		*v = Variant(decoded)
   219		for key := range fields {
   220			if fmt.Sprint(key) == "attachment" && v.Attachment == nil {
   221				v.attachmentSet = true
   222				break
   223			}
   224		}
   225		return nil
   226	}

