 49			variant string
 50		}
 51		createdVariants := make(map[variantKey]*flipt.Variant)
 52	
 53		for _, f := range doc.Flags {
 54			if f == nil {
 55				continue
 56			}
 57			if _, err := i.store.CreateFlag(ctx, &flipt.CreateFlagRequest{
 58				Key:         f.Key,
 59				Name:        f.Name,
 60				Description: f.Description,
 61				Enabled:     f.Enabled,
 62			}); err != nil {
 63				return fmt.Errorf("importing flag %q: %w", f.Key, err)
 64			}
 65	
 66			for _, v := range f.Variants {
 67				if v == nil {
 68					continue
 69				}
 70				attachment, err := importAttachment(v)
 71				if err != nil {
 72					return fmt.Errorf("encoding attachment for variant %q on flag %q: %w", v.Key, f.Key, err)
 73				}
 74				created, err := i.store.CreateVariant(ctx, &flipt.CreateVariantRequest{
 75					FlagKey:     f.Key,
 76					Key:         v.Key,
 77					Name:        v.Name,
 78					Description: v.Description,
 79					Attachment:  attachment,
 80				})
 81				if err != nil {
 82					return fmt.Errorf("importing variant %q on flag %q: %w", v.Key, f.Key, err)
 83				}
 84				createdVariants[variantKey{flag: f.Key, variant: v.Key}] = created
 85			}
 86		}
 87	
 88		for _, s := range doc.Segments {
 89			if s == nil {
 90				continue
 91			}
 92			if _, err := i.store.CreateSegment(ctx, &flipt.CreateSegmentRequest{
 93				Key:         s.Key,
 94				Name:        s.Name,
 95				Description: s.Description,
 96			}); err != nil {
 97				return fmt.Errorf("importing segment %q: %w", s.Key, err)
 98			}
 99	
100			for _, c := range s.Constraints {
101				if c == nil {
102					continue
103				}
104				if _, err := i.store.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
105					SegmentKey: s.Key,
106					Type:       flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
107					Property:   c.Property,
108					Operator:   c.Operator,
109					Value:      c.Value,
110				}); err != nil {
111					return fmt.Errorf("importing constraint for segment %q: %w", s.Key, err)
112				}
113			}
114		}
115	
116		for _, f := range doc.Flags {
117			if f == nil {
118				continue
119			}
120			for _, r := range f.Rules {
121				if r == nil {
122					continue
123				}
124				rule, err := i.store.CreateRule(ctx, &flipt.CreateRuleRequest{
125					FlagKey:    f.Key,
126					SegmentKey: r.SegmentKey,
127					Rank:       int32(r.Rank),
128				})
129				if err != nil {
130					return fmt.Errorf("importing rule for flag %q: %w", f.Key, err)
131				}
132	
133				for _, d := range r.Distributions {
134					if d == nil {
135						continue
136					}
137					variant, found := createdVariants[variantKey{flag: f.Key, variant: d.VariantKey}]
138					if !found || variant == nil {
139						return fmt.Errorf("finding variant %q on flag %q", d.VariantKey, f.Key)
140					}
141					if _, err := i.store.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
142						FlagKey:   f.Key,
143						RuleId:    rule.Id,
144						VariantId: variant.Id,
145						Rollout:   d.Rollout,
146					}); err != nil {
147						return fmt.Errorf("importing distribution for flag %q: %w", f.Key, err)
148					}
149				}
150			}
151		}
152	
153		return nil
154	}
155	
156	func importAttachment(v *Variant) (string, error) {
157		if v.Attachment == nil {
158			if v.attachmentSet {
159				return "null", nil
160			}
161			return "", nil
162		}
163	
164		attachment := convert(v.Attachment)
165		if raw, ok := attachment.(string); ok && json.Valid([]byte(raw)) {
166			var compact bytes.Buffer
167			if err := json.Compact(&compact, []byte(raw)); err != nil {
168				return "", err
169			}
170			return compact.String(), nil
171		}
172	
173		data, err := json.Marshal(attachment)
174		if err != nil {
175			return "", err
176		}
177		return string(data), nil
178	}
179	
180	// convert recursively changes YAML's interface-keyed maps to string-keyed maps
181	// so they can be encoded as JSON.
182	func convert(value interface{}) interface{} {
183		switch value := value.(type) {
184		case map[interface{}]interface{}:
185			converted := make(map[string]interface{}, len(value))
186			for key, item := range value {
187				converted[fmt.Sprint(key)] = convert(item)
188			}
189			return converted
190		case map[string]interface{}:
191			converted := make(map[string]interface{}, len(value))
192			for key, item := range value {
193				converted[key] = convert(item)
194			}
195			return converted
196		case []interface{}:
197			converted := make([]interface{}, len(value))
198			for index, item := range value {
199				converted[index] = convert(item)
200			}
201			return converted
202		default:
203			return value
204		}
205	}
206	
207	func (v *Variant) UnmarshalYAML(unmarshal func(interface{}) error) error {
208		type variantAlias Variant
209		var decoded variantAlias
210		if err := unmarshal(&decoded); err != nil {
211			return err
212		}
213		var fields map[interface{}]interface{}
214		if err := unmarshal(&fields); err != nil {
215			return err
216		}
217	
218		*v = Variant(decoded)
219		for key := range fields {
220			if fmt.Sprint(key) == "attachment" && v.Attachment == nil {
221				v.attachmentSet = true
222				break
223			}
224		}
225		return nil
226	}
